#pragma once
#include "rinkfit/joint_finite_source_paths_v1.hpp"
#include <ceres/jet.h>
namespace rinkfit {
struct JointObservedCurveFootV1{bool valid=false;int path=-1;double station=0,squared_error=INFINITY,gradient=NAN,tangent_error=NAN,normal_error=NAN,tangent_speed=NAN;std::array<double,2>prediction{};std::size_t evaluations=0,local_basins=0;};
// Initialization-only: physical parameters and original source_y are fixed.
// Reuse the existing 32-cell chart navigation, refining EVERY sampled basin.
// This is broad finite-chart navigation, not a mathematical global lower-bound certificate.
inline JointObservedCurveFootV1 profile_joint_observed_curve_v1(const JointEventModel&m,const JointPacket&p,std::size_t index){
 const auto&r=p.rows.at(index);JointObservedCurveFootV1 best;best.station=r.station;best.path=r.path;std::vector<int>paths=r.kind==1?std::vector<int>{r.path}:joint_source_allowed_finite_paths_v1(p,m,index);
 for(int path:paths){const auto l=m.layout(m.shot_map.at(r.shot_id),r.material,path,r.pts,r.width_block,r.width_sign);const auto ptr=m.pointers(l);auto cost=[&](double s){++best.evaluations;if(!r.station_allowed(m,path,s))return double(INFINITY);auto v=m.predict_for_al(l,s,r.uv[1],ptr.data());if(!v.arithmetic_valid||v.physical_status!=DomainStatus::kValid||!(v.depth>0))return double(INFINITY);const auto visible=m.visibility(l,s,r.uv[1],ptr.data());if(!visible.visible()||m.measurement_domain(l,s,ptr.data(),5)>0||m.measurement_domain(l,s,ptr.data(),6)>0)return double(INFINITY);const double a=v.uv[0]-r.uv[0],b=v.uv[1]-r.uv[1];return a*a+b*b;};auto consider=[&](double s){const double f=cost(s);if(f<best.squared_error){best.valid=true;best.path=path;best.station=s;best.squared_error=f;best.prediction=m.predict_for_al(l,s,r.uv[1],ptr.data()).uv;}};
 if(r.kind==1){consider(r.station);continue;}for(auto interval:r.station_intervals(m,path)){std::vector<double>breaks{interval[0],interval[1]};const auto&shape=m.materials.at(r.material).paths.at(path);if((shape.kind==2||shape.kind==6||shape.kind==7)&&shape.points.size()>1)for(std::size_t k=1;k+1<shape.points.size();++k){double s=double(k)/(shape.points.size()-1);if(s>interval[0]&&s<interval[1])breaks.push_back(s);}std::sort(breaks.begin(),breaks.end());if(path==r.path&&r.station>=interval[0]&&r.station<=interval[1])consider(r.station);for(std::size_t segment=1;segment<breaks.size();++segment){const double a=breaks[segment-1],b=breaks[segment];std::array<double,33>x{},f{};for(int k=0;k<=32;++k){x[k]=a+(b-a)*k/32.;f[k]=cost(x[k]);if(std::isfinite(f[k]))consider(x[k]);}for(int k=0;k<=32;++k)if(std::isfinite(f[k])&&(k==0||f[k]<=f[k-1])&&(k==32||f[k]<=f[k+1])){++best.local_basins;double lo=x[std::max(0,k-1)],hi=x[std::min(32,k+1)];while(true){double u=lo+(hi-lo)*.3819660112501051,v=lo+(hi-lo)*.6180339887498949;if(!(u>lo&&v>u&&v<hi))break;const double fu=cost(u),fv=cost(v);if(fu<fv)hi=v;else lo=u;}consider(lo);consider(hi);consider((lo+hi)*.5);}}}
 }
 if(best.valid){const auto l=m.layout(m.shot_map.at(r.shot_id),r.material,best.path,r.pts,r.width_block,r.width_sign);using K=ceres::Jet<double,1>;std::vector<std::vector<K>>v;std::vector<const K*>ptr;for(int id:l.block_ids){v.emplace_back();for(double x:m.blocks.at(id).values)v.back().emplace_back(x);}for(const auto&x:v)ptr.push_back(x.data());K station(best.station);station.v[0]=1;const auto uv=m.predict_explicit(l,station,K(r.uv[1]),ptr.data());if(uv.valid()){const double dx=uv.uv[0].a-r.uv[0],dy=uv.uv[1].a-r.uv[1],tx=uv.uv[0].v[0],ty=uv.uv[1].v[0];best.gradient=2*(dx*tx+dy*ty);best.tangent_speed=std::hypot(tx,ty);if(best.tangent_speed>0){best.tangent_error=(dx*tx+dy*ty)/best.tangent_speed;best.normal_error=(dx*ty-dy*tx)/best.tangent_speed;}}}return best;
}
}
